def get_Inv_Count(arr):
    # Function to merge two sorted halves and count inversions
    def merge_sort_and_count(arr, left, right):
        if left >= right:
            return 0

        mid = (left + right) // 2
        inv_count = merge_sort_and_count(arr, left, mid)
        inv_count += merge_sort_and_count(arr, mid + 1, right)
        inv_count += merge_and_count(arr, left, mid, right)
        return inv_count

    # Function to merge two sorted subarrays and count inversions
    def merge_and_count(arr, left, mid, right):
        temp = []
        i = left
        j = mid + 1
        inv_count = 0

        while i <= mid and j <= right:
            if arr[i] <= arr[j]:
                temp.append(arr[i])
                i += 1
            else:
                temp.append(arr[j])
                inv_count += (mid - i + 1)
                j += 1

        while i <= mid:
            temp.append(arr[i])
            i += 1

        while j <= right:
            temp.append(arr[j])
            j += 1

        for k in range(len(temp)):
            arr[left + k] = temp[k]

        return inv_count

    return merge_sort_and_count(arr, 0, len(arr) - 1)
