def count_binary_seq(n):
    def count_sequences_with_sum(k, target_sum):
        # Returns the number of binary sequences of length k that sum to target_sum
        if target_sum < 0 or target_sum > k:
            return 0
        if k == 0:
            return 1 if target_sum == 0 else 0
        # Using dynamic programming approach to compute the number of sequences
        dp = [0] * (target_sum + 1)
        dp[0] = 1
        for i in range(1, k + 1):
            new_dp = [0] * (target_sum + 1)
            for j in range(target_sum + 1):
                if dp[j] > 0:
                    if j + 1 <= target_sum:
                        new_dp[j + 1] += dp[j]
                    new_dp[j] += dp[j]
            dp = new_dp
        return dp[target_sum]

    if n == 0:
        return 1
    total = 0
    max_sum = n
    for sum_first in range(0, max_sum + 1):
        sum_second = sum_first
        total += count_sequences_with_sum(n, sum_first) * count_sequences_with_sum(n, sum_second)
    return total
